import StyleDictionary from 'style-dictionary';

const commonSource = [
  'src/primitive/color.json',
  'src/primitive/size.json',
  'src/primitive/typography.json',
  'src/semantic/size.json',
  'src/semantic/typography.json',
];

export default {
  // src/code/* = tokens authored in code, not exported from Figma (src/
  // primitive + src/semantic are regenerated by scripts/convert-figma-
  // tokens.py and would overwrite hand edits). color.light.json is a
  // light-only override of a Figma value and must come after it.
  source: [...commonSource, 'src/semantic/color.default.json', 'src/code/color.json', 'src/code/foundation.json', 'src/code/color.light.json'],
  platforms: {
    css: {
      transforms: [
        'attribute/cti',
        'name/kebab',
        'time/seconds',
        'html/icon',
        'size/px',
        'color/css',
        'asset/url',
        'fontFamily/css',
        'cubicBezier/css',
      ],
      buildPath: 'build/css/',
      files: [
        {
          destination: 'variables.css',
          format: 'css/variables',
          options: { selector: ':root' },
        },
      ],
    },
    js: {
      transformGroup: 'js',
      buildPath: 'build/js/',
      files: [
        {
          destination: 'tokens.js',
          format: 'javascript/es6',
        },
        {
          destination: 'tokens.d.ts',
          format: 'typescript/es6-declarations',
        },
      ],
    },
    'tailwind-json': {
      transformGroup: 'js',
      buildPath: 'build/tailwind/',
      files: [
        {
          destination: 'tokens.json',
          format: 'json/nested',
        },
      ],
    },
  },
};

// Dark theme is built separately — see build-dark.mjs — because Style
// Dictionary resolves one value per token per run. We swap
// src/semantic/color.default.json for src/semantic/color.dark.json
// and re-run against a different output file (variables-dark.css).
